INSERT INTO "task_definition" ("task_id","schema_version","title","objective","source_path","status_detail","explicit_activation_required","intake_path","archive_path","archive_sha256") VALUES ('harness.simplify-2.adapter-retirement',3,'Audit and decompose project-local adapters','Audit and decompose project-local adapters by assigning each adapter behavior to its contract owner while preserving the supported nine-name public surface and compatibility facade.','harness/tasks/harness.simplify-2.adapter-retirement.json','completed post-review reconciliation: 9 adapters audited, 9 relocated, 0 removed, 9 public imports preserved, and 9 execute signatures preserved; no successor activated',1,NULL,NULL,NULL);
INSERT INTO "task_definition" ("task_id","schema_version","title","objective","source_path","status_detail","explicit_activation_required","intake_path","archive_path","archive_sha256") VALUES ('harness.simplify-2.cli-consolidation',3,'Consolidate maintained CLI scripts under python/src/cli','Consolidate maintained live harness commands under `python/src/cli/` and expose one explicit synchronization surface that invokes the existing full `HarnessControlMigrator`, while keeping reusable behavior with its owning ActionObjects and preserving historical command evidence.','harness/tasks/harness.simplify-2.cli-consolidation.json','inactive R2.6 final CLI placement and control-synchronization work package',0,NULL,NULL,NULL);
INSERT INTO "task_definition" ("task_id","schema_version","title","objective","source_path","status_detail","explicit_activation_required","intake_path","archive_path","archive_sha256") VALUES ('harness.simplify-2.control-decomposition',3,'Decompose SQLite-hybrid control ownership','Extract repository-specific SQLite-hybrid control construction into `python/src/ksdft2effmass/harness/pi/local/dbcontrol/`, relocate project-neutral read-only SQLite Task-state database reading, query, and private inspection behavior into `python/src/ksdft2effmass/harness/pi/dbcontrol/`, then remove the superseded modules after all consumers have migrated.','harness/tasks/harness.simplify-2.control-decomposition.json','completed with bounded post-review boundary corrections; no successor activated',1,NULL,NULL,NULL);
INSERT INTO "task_definition" ("task_id","schema_version","title","objective","source_path","status_detail","explicit_activation_required","intake_path","archive_path","archive_sha256") VALUES ('harness.simplify-2.python-conformance-decomposition',3,'Simplify the maintained Python evidence system','Make Python evidence authority and profile semantics explicit, derive one immutable parsed module model with independent rules, and prepare reconstructible evidence inputs for the existing full `HarnessControlMigrator` while preserving meaningful evidence identities and claims.','harness/tasks/harness.simplify-2.python-conformance-decomposition.json','active R2.3 resumed after HC01 resolved the custom routine evidence-profile contract; no successor activated',0,NULL,NULL,NULL);
INSERT INTO "task_definition" ("task_id","schema_version","title","objective","source_path","status_detail","explicit_activation_required","intake_path","archive_path","archive_sha256") VALUES ('harness.simplify-2.resource-decomposition',3,'Decompose resource resolution and routing ownership','Decompose resource records, manifest semantics, resolution, refresh or projection, and skill-resource closure while preparing explicit resource inputs for the same full `HarnessControlMigrator` reconstruction.','harness/tasks/harness.simplify-2.resource-decomposition.json','inactive R2.4 resource-authority and canonical-input work package',0,NULL,NULL,NULL);
INSERT INTO "task_definition" ("task_id","schema_version","title","objective","source_path","status_detail","explicit_activation_required","intake_path","archive_path","archive_sha256") VALUES ('harness.simplify-2.validation-retirement',3,'Consolidate validation and retire replay machinery','Compose evidence, resource, Task, wire, and other repository validation results into one structured maintained result, extract one narrow private control-generation builder for candidate-based publication and nonmutating conformance, and retire replay, nested CLI validation, and duplicated cross-domain gates.','harness/tasks/harness.simplify-2.validation-retirement.json','inactive R2.7 repository validation, private control-generation builder, and legacy-route retirement work package',0,NULL,NULL,NULL);
INSERT INTO "task_definition" ("task_id","schema_version","title","objective","source_path","status_detail","explicit_activation_required","intake_path","archive_path","archive_sha256") VALUES ('harness.simplify-2.wire-validation-decomposition',3,'Decompose canonical JSON and domain wire codecs','Decompose `python/src/ksdft2effmass/harness/pi/validation.py` into canonical JSON support, explicit domain codecs, and thin wire-kind dispatch without changing database construction, publication, or synchronization ownership.','harness/tasks/harness.simplify-2.wire-validation-decomposition.json','inactive R2.5 wire-codec decomposition with unchanged persistence ownership',0,NULL,NULL,NULL);
