INSERT INTO "task_definition" ("task_id","schema_version","title","objective","source_path","status_detail","explicit_activation_required","intake_path","archive_path","archive_sha256") VALUES ('human-review-interface.human-decision-recording',3,'Implement pure human decision recording','This bounded slice adds the immutable public `HumanReviewDecision` ResultObject and fieldless `HumanReviewDecisionRecorder` ActionObject. Following the human-requested architecture correction, the decision stores the exact immutable packet itself, exact human response, caller-supplied normalized disposition, and contract-compatible explicit scope. Recording reconstructs the canonical `HumanReviewPreparer` result and rejects a packet whose relationships, ordering, or derived status differ. Recording performs no natural-language interpretation, authority inference, persistence, filesystem or Git action, checkpoint mutation, or successor activation.','harness/tasks/human-review-interface.human-decision-recording.json','architecture_corrected_awaiting_human_review under `.pi/chains/human-review-interface.chain.json`',0,NULL,'harness/archive/task-control-v1/tasks/human-review-interface.human-decision-recording.md','2239ace57b7e01415975dba368483903045fc1fdd7ca137e36983517efb5fbb3');
