INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('ARCHITECTURE-DECISION-SKILL-1','authorized_scope',0,'It creates and activates the read-only `develop-architecture-decision` skill, canonical/reference/descriptor resources, byte-identical live resources, controlled H6-only fixtures and validator, generic/local manifest and profile synchronization, eight-skill inventory/validation, current local replay, selected local route, maintained harness documentation, and task evidence.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('ARCHITECTURE-DECISION-SKILL-1','completion_criterion',0,'Run ownership preflight with the task-specific chain:');
