INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.documentation-correction','authorized_scope',0,'Apply deterministic corrections directly, including stale status, activation, prerequisite, successor, completion, or acceptance prose whose operational owner is a chain or Task record; obsolete names and links; manual restatements that will be replaced by generated control-reference pages; historical material that is not clearly labeled historical; and naming that violates an accepted convention.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.documentation-correction','authorized_scope',1,'Resolve only the remaining ambiguity queue, asking the human only when applicable claims conflict, precedence does not resolve them, and materially different defensible corrections remain.');
