INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.publication.hierarchy','completion_criterion',0,'Completion requires the applied path map, resolved links, correct generated/external/source treatment, preserved content identities, and a compact handoff to `harness.simplification.docs-json.authority-catalog`.');
