INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.publication.triage','authorized_scope',0,'Inventory `docs/conferences/` and `docs/papers/`, apply deterministic classifications where repository evidence permits only one reasonable result, and send only genuinely ambiguous files for human classification before hierarchy changes.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.publication.triage','authorized_scope',1,'Additional roots require current human authorization. Bind the inventory to one Git revision or accepted worktree state. For tracked files, path and Git object identity are sufficient; hash only content not identified by Git. Record symlinks without following them outside the selected roots.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.publication.triage','completion_criterion',0,'Produce one temporary triage record containing the bounded inventory, deterministic classifications with reasons, and the ambiguity queue. Completion requires complete selected-root path coverage, no duplicate paths, disposition of every ambiguity, and a compact input for `harness.simplification.docs-json.publication.hierarchy`.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.publication.triage','completion_criterion',1,'The temporary record is `.pi/evidence/docs-json/publication-triage.json`. It covers 23 regular files at revision `107f6b1d39be1af460c03183e880d3063f1320a0`: 22 tracked files by Git object identity and one untracked `.DS_Store` by SHA-256. Twenty-one classifications are deterministic. The human PI disposed the remaining cases by authorizing deletion of `LA2.pdf` and assigning the empty `ksdft2effmass.paper.md` as the publication-root index at `docs/publications/ksdft2effmass.publications.00.md`. Independent review identified the empty file as a missing ambiguity before that human disposition. The accepted record is the compact input to `harness.simplification.docs-json.publication.hierarchy`.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.publication.triage','completion_criterion',2,'This Task does not move, rename, delete, rewrite, publish, submit, or release files. Human authorization activates only this bounded inventory and triage.');
