INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.task-document-migration','authorized_scope',0,'The selected source paths remain exactly .pi/tasks/harness.simplification.docs-json.md, .pi/tasks/harness.simplification.docs-json.publication.md, .pi/tasks/harness.simplification.docs-json.publication.triage.md, .pi/tasks/harness.simplification.docs-json.publication.hierarchy.md, .pi/tasks/harness.simplification.docs-json.authority-catalog.md, and .pi/tasks/harness.simplification.docs-json.documentation-correction.md.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.task-document-migration','authorized_scope',1,'Begin only after harness.simplification.docs-json.task-implementation-hardening is completed and explicitly human-accepted and this Stage-2B Task receives a separate human activation decision.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.task-document-migration','authorized_scope',2,'Prepare exactly one immutable migration packet at a time in the accepted order; stop for its explicit human disposition and complete any accepted migration verification before preparing a later packet.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.task-document-migration','authorized_scope',3,'Each packet presents a concise human-readable before/after view containing the original Markdown, candidate canonical JSON, candidate maintained documentation, explanation of content moved to each destination, exact unexplained differences, opaque-content preservation result, rollback identity, and a simple accept, revise, retain Markdown, or defer decision.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.task-document-migration','authorized_scope',4,'The packet may link to detailed mappings, exact identities, and validation evidence but must not require the human to read raw mappings, command transcripts, or every test to understand the file decision.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.task-document-migration','authorized_scope',5,'Apply only an explicitly accepted current-file migration, verify canonical round trip, rendered documentation, exact comparison, graph and mixed-format compatibility, retained evidence, rollback identity, and unchanged later sources, then stop or prepare the next packet only when authorized by the current disposition.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.task-document-migration','authorized_scope',6,'If any file reveals a required material change to accepted public fields, signatures, ownership boundaries, wire behavior, rendering ownership, comparison claims, or packet semantics, stop without changing the contract and return to explicit human contract review.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.task-document-migration','completion_criterion',0,'Stage 2A implementation acceptance and Stage-2B activation are durably recorded before the first real packet is prepared.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.task-document-migration','completion_criterion',1,'Each selected file has exactly one human-readable immutable packet and one exact human disposition, and no later file is prepared before the current file is dispositioned and any accepted migration is verified.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.task-document-migration','completion_criterion',2,'Every packet contains all eight required before/after elements and clearly distinguishes explained mapped transformations from exact unexplained differences and human acceptance.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.task-document-migration','completion_criterion',3,'LaTeX, Mermaid, code fences, directives, tables, links, and other opaque project content remain byte-identical unless the exact file disposition accepts a stated transformation.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.task-document-migration','completion_criterion',4,'A revise decision changes only the current candidate within accepted authority; retain Markdown leaves that source authoritative and unmigrated; defer postpones it without implied acceptance; a required contract change stops the Task.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.task-document-migration','completion_criterion',5,'All accepted files pass canonical round trip, complete rendering, exact byte-structural comparison, graph validation, mixed-format inspection, rollback-identity, and focused verification checks while undispositioned Markdown sources remain authoritative and unchanged.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.task-document-migration','completion_criterion',6,'All six file decisions and verifications are complete, but the chain remains operational authority and no selection-state implementation, chain cutover, deletion, or automatic successor activation occurs.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.task-document-migration','exclusion',0,'Do not activate before Stage 2A is human-accepted and a separate Stage-2B activation checkpoint is resolved as approval.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.task-document-migration','exclusion',1,'Do not batch files, prepare a later packet early, infer acceptance from silence, tests, or review, or apply a migration without the exact current-file human disposition.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.task-document-migration','exclusion',2,'Do not reopen or silently modify the accepted Stage-1 contract or accepted Stage-2A public implementation through a file migration.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.task-document-migration','exclusion',3,'Do not normalize, reflow, reinterpret, or silently drop opaque content, documentation-owned narrative, historical evidence, or unexplained differences.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.task-document-migration','exclusion',4,'Do not implement selection state, cut over or delete the chain, migrate Tasks outside the six selected files, add dependencies, change lockfiles, or perform SQLite, telemetry, scientific, publication, external, protected, release, or unrelated harness work.');
