INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.task-model-contract','authorized_scope',7,'Define HarnessTaskMigrationReviewPacketPreparer as a stateless ActionObject with execute(request: HarnessTaskMigrationReviewPacketRequest) -> HarnessTaskMigrationReviewPacket; assign all cross-object identity, complete ordered nonoverlapping coverage, source-reference, Task/JSON, documentation/span, profile/rendering, comparison, generic-review target/revision, and deterministic packet-construction validation to the preparer without duplicating generic HumanReviewPreparer semantics.');
INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.docs-json.task-model-contract','authorized_scope',8,'Preserve HarnessTaskMigrationReviewPacket as the immutable preparer result, HumanReviewDecisionRecorder as owner of the generic human decision, and HarnessTaskMigrationFileDispositionRecorder as the migration-domain action validating the exact packet/decision relationship; none may interpret human authority.');
