INSERT INTO "task_text" ("task_id","text_kind","ordinal","value") VALUES ('harness.simplification.round-2.sqlite-hybrid-cutover','completion_criterion',0,'The deterministic database, SQL recovery representation, projections, reader cutover, and bounded validation agree.');
